"""Verified local model installation from pinned public Hugging Face snapshots."""
import ctypes
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import tempfile
import time
from urllib.parse import quote, urlsplit
from urllib.request import Request, urlopen


CATALOG_PATH = "config/model-catalog.json"
METADATA_NAME = ".installed-model.json"
REQUIRED = {"config.json", "model.bin", "tokenizer.json"}
SAFE_FILE = re.compile(r"[A-Za-z0-9_.-]+")
SAFE_MODEL = re.compile(r"[A-Za-z0-9_.-]+")
SAFE_REPO = re.compile(r"[A-Za-z0-9_-]+/[A-Za-z0-9_.-]+")
PINNED_REVISION = re.compile(r"[a-f0-9]{40}")
SHA256 = re.compile(r"[a-f0-9]{64}")


def _catalog(root):
    catalog = json.loads((Path(root) / CATALOG_PATH).read_text(encoding="utf-8"))
    if catalog.get("format") != 2 or catalog.get("model_root") != "models":
        raise ValueError("Unsupported model catalog")
    models = catalog.get("models")
    if not isinstance(models, dict) or set(models) != {"small", "large-v3-turbo"}:
        raise ValueError("Unsupported model catalog entries")
    return catalog


def manifest_for(root, model_id):
    if not SAFE_MODEL.fullmatch(model_id or ""):
        raise ValueError("Invalid logical model id")
    manifest = _catalog(root)["models"].get(model_id)
    if not isinstance(manifest, dict) or manifest.get("id") != model_id:
        raise ValueError("Unsupported model: " + str(model_id))
    if manifest.get("directory") != model_id or not SAFE_REPO.fullmatch(manifest.get("source", "")):
        raise ValueError("Invalid model source/directory")
    if any(part in (".", "..") for part in manifest["source"].split("/")):
        raise ValueError("Invalid model source path")
    if not PINNED_REVISION.fullmatch(manifest.get("revision", "")):
        raise ValueError("Model must use a pinned commit revision")
    runtime = manifest.get("runtime", {})
    if runtime.get("format") != "CTranslate2" or not runtime.get("compatible"):
        raise ValueError("Model is incompatible with this runtime")
    files = manifest.get("files")
    if not isinstance(files, list):
        raise ValueError("Invalid model file list")
    seen = set()
    for item in files:
        name = item.get("name", "")
        path = PurePosixPath(name)
        if (len(path.parts) != 1 or name in (".", "..") or not SAFE_FILE.fullmatch(name) or name in seen or
                name.lower().endswith((".exe", ".dll", ".pyd", ".bat", ".cmd", ".ps1"))):
            raise ValueError("Unsafe or duplicate model file")
        if not SHA256.fullmatch(item.get("sha256", "")):
            raise ValueError("Model file SHA-256 is not pinned")
        if not isinstance(item.get("bytes"), int) or item["bytes"] <= 0:
            raise ValueError("Model file size is not pinned")
        seen.add(name)
    if not REQUIRED <= seen:
        raise ValueError("Incomplete model manifest")
    return manifest


def _manifest_hash(manifest):
    payload = json.dumps(manifest, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def valid_file(path, item):
    if not path.is_file() or path.stat().st_size != item["bytes"]:
        return False
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest() == item["sha256"]


def _valid_snapshot(target, manifest):
    return all(valid_file(target / item["name"], item) for item in manifest["files"])


def _metadata(manifest):
    return {
        "format": 1,
        "model": manifest["id"],
        "source": manifest["source"],
        "revision": manifest["revision"],
        "manifest_sha256": _manifest_hash(manifest),
        "runtime": manifest["runtime"],
    }


def _write_metadata(target, manifest):
    data = json.dumps(_metadata(manifest), indent=2, ensure_ascii=False) + "\n"
    fd, temporary = tempfile.mkstemp(prefix=".installed-model-", suffix=".tmp", dir=target)
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, target / METADATA_NAME)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def ask_download(manifest, files):
    from .tray_i18n import startup_language
    size = sum(item["bytes"] for item in files) / 1024**3
    name = manifest["id"]
    if startup_language() == "ru":
        message = (f"Модель {name} отсутствует или не прошла проверку.\n\n"
                   f"Скачать {size:.2f} GiB с Hugging Face?\n"
                   "Версия закреплена, snapshot будет проверен по SHA-256.\n"
                   "После установки распознавание работает локально без интернета.")
    else:
        message = (f"The {name} model is missing or failed verification.\n\n"
                   f"Download {size:.2f} GiB from Hugging Face?\n"
                   "The revision is pinned and the snapshot will be verified by SHA-256.\n"
                   "After installation, speech recognition works locally without internet.")
    return ctypes.windll.user32.MessageBoxW(None, message, "EXPC-WLK", 0x24) == 6


def show_progress(completed, total):
    from . import system_tray
    from .tray_i18n import startup_language
    icon = system_tray._startup_icon or system_tray._active_icon
    if icon is not None:
        label = "Загрузка модели" if startup_language() == "ru" else "Downloading model"
        icon.title = f"EXPC-WLK — {label}: {completed * 100 // total}%"


def _download_file(manifest, item, destination, completed, total, progress, opener):
    source = quote(manifest["source"], safe="/")
    revision = quote(manifest["revision"], safe="")
    name = quote(item["name"], safe="")
    url = f"https://huggingface.co/{source}/resolve/{revision}/{name}?download=true"
    request = Request(url, headers={"User-Agent": "EXPC-WLK-model-download"})
    digest = hashlib.sha256()
    received = 0
    last_progress = 0.0
    with destination.open("xb") as output, opener(request, timeout=30) as response:
        final = urlsplit(response.url)
        host = (final.hostname or "").lower()
        if final.scheme != "https" or not (
                host == "huggingface.co" or host.endswith((".huggingface.co", ".hf.co"))):
            raise ValueError("Unexpected model download host")
        while chunk := response.read(1024**2):
            received += len(chunk)
            if received > item["bytes"]:
                raise ValueError("Model download exceeds pinned size")
            output.write(chunk)
            digest.update(chunk)
            now = time.monotonic()
            if now - last_progress > 0.5:
                progress(completed + received, total)
                last_progress = now
        output.flush()
        os.fsync(output.fileno())
    if received != item["bytes"] or digest.hexdigest() != item["sha256"]:
        raise ValueError("Model SHA-256 verification failed: " + item["name"])
    progress(completed + received, total)
    print("MODEL_VERIFIED " + item["name"], flush=True)
    return received


def ensure_model(root, model_id, consent=None, progress=None, opener=urlopen, model_root=None):
    root = Path(root).resolve()
    manifest = manifest_for(root, model_id)
    models = Path(model_root).resolve() if model_root else (root / "models").resolve()
    if model_root is None and (models != root / "models" or root not in models.parents):
        raise ValueError("Portable model root must remain inside the application")
    models.mkdir(parents=True, exist_ok=True)
    target = (models / manifest["directory"]).resolve()
    if target.parent != models or target.name != manifest["directory"]:
        raise ValueError("Invalid local model target")

    if _valid_snapshot(target, manifest):
        expected = _metadata(manifest)
        try:
            installed = json.loads((target / METADATA_NAME).read_text(encoding="utf-8"))
        except (OSError, ValueError):
            installed = None
        if installed != expected:
            _write_metadata(target, manifest)
        return target

    files = manifest["files"]
    if not (consent or ask_download)(manifest, files):
        raise RuntimeError("Model download cancelled / Загрузка модели отменена.")

    progress = progress or show_progress
    staging = Path(tempfile.mkdtemp(prefix=".staging-" + model_id + "-", dir=models))
    previous = None
    try:
        total = sum(item["bytes"] for item in files)
        completed = 0
        for item in files:
            completed += _download_file(
                manifest, item, staging / item["name"], completed, total, progress, opener
            )
        if not _valid_snapshot(staging, manifest):
            raise ValueError("Incomplete model snapshot after download")
        _write_metadata(staging, manifest)

        if target.exists():
            previous = Path(tempfile.mkdtemp(prefix=".previous-" + model_id + "-", dir=models))
            previous.rmdir()
            os.replace(target, previous)
        try:
            os.replace(staging, target)
        except Exception:
            if previous is not None and previous.exists() and not target.exists():
                os.replace(previous, target)
            raise
        if previous is not None:
            shutil.rmtree(previous)
            previous = None
        return target
    finally:
        if staging.exists():
            shutil.rmtree(staging)
        if previous is not None and previous.exists() and not target.exists():
            os.replace(previous, target)
